--[[
  Obsidian Shader Hub XL — functional density build
  Every table and function is used. Defaults OFF.
]]

local Players = game:GetService("Players")
local Lighting = game:GetService("Lighting")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local Debris = game:GetService("Debris")
local LP = Players.LocalPlayer
local Cam = workspace.CurrentCamera

local REPO = "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/"

local function http(path)
	local ok, body = pcall(function() return game:HttpGet(REPO .. path) end)
	if ok and type(body) == "string" and #body > 50 then return body end
	return nil
end

local function loadLib(path)
	local src = http(path)
	if not src then return nil end
	local fn = loadstring(src)
	if not fn then return nil end
	local ok, res = pcall(fn)
	if ok then return res end
	return nil
end

local Library = loadLib("Library.lua")
if not Library then warn("[OSH] Library fail") return end
local ThemeManager = loadLib("addons/ThemeManager.lua")
local SaveManager = loadLib("addons/SaveManager.lua")

local Orig = {}
local function snap()
	for _, k in ipairs({
		"Brightness","ClockTime","FogEnd","FogStart","FogColor","Ambient","OutdoorAmbient",
		"ColorShift_Top","ColorShift_Bottom","EnvironmentDiffuseScale","EnvironmentSpecularScale",
		"ExposureCompensation","GeographicLatitude","GlobalShadows","ShadowSoftness","Technology"
	}) do
		Orig[k] = Lighting[k]
	end
	Orig.Sky = Lighting:FindFirstChildOfClass("Sky")
end
snap()

