	Quality=2,
}

local cycleConn, weatherConn, grainConn

local function kill(key)
	if FX[key] then pcall(function() FX[key]:Destroy() end) FX[key]=nil end
end

local function make(className, key)
	kill(key)
	local e = Instance.new(className)
	e.Name = "OSH_"..key
	e.Parent = Lighting
	FX[key] = e
	return e
end

local function clearWeather()
	for _, p in ipairs(WeatherParts) do pcall(function() p:Destroy() end) end
	WeatherParts = {}
	if weatherConn then weatherConn:Disconnect() weatherConn=nil end
end

