    CC = true, CCBright = 0.18, CCContrast = 0.02, CCSat = -0.34,
    CCTint = Color3.fromRGB(68,251,82),
    DoF = false, DoFFar = 0.65, DoFFocus = 39, DoFIn = 24, DoFNear = 0.45,
    Sun = true, SunInt = 0.17, SunSpread = 0.85,
    Blur = false, BlurSize = 21,
    Atmo = false, AtmoDen = 0.67, AtmoOff = 0.55,
    AtmoGlare = 0.60, AtmoHaze = 4.30,
    AtmoCol = Color3.fromRGB(104,226,154),
    AtmoDec = Color3.fromRGB(7,32,118),
    Clock = 13, Bright = 3.1, Exposure = 0.4,
    FogEnd = 2150, FogStart = 190, Shadows = true, FullBright = false,
    SkyId = 33, GradeId = 6,
  },
}

local function applyBloom()
	kill("Bloom")
	if not (S.Master and S.Bloom) then return end
	local b = make("BloomEffect","Bloom")
	b.Intensity = S.BloomInt
	b.Size = S.BloomSize
	b.Threshold = S.BloomThresh
end

local function applyCC()
	kill("CC")
	if not (S.Master and S.CC) then return end
	local c = make("ColorCorrectionEffect","CC")
	c.Brightness = S.CCBright
	c.Contrast = S.CCContrast
	c.Saturation = S.CCSat
	c.TintColor = S.CCTint
end

local function applyDoF()
	kill("DoF")
	if not (S.Master and S.DoF) then return end
	local d = make("DepthOfFieldEffect","DoF")
	d.FarIntensity = S.DoFFar
	d.FocusDistance = S.DoFFocus
	d.InFocusRadius = S.DoFIn
	d.NearIntensity = S.DoFNear
end

local function applySun()
	kill("Sun")
	if not (S.Master and S.Sun) then return end
	local s = make("SunRaysEffect","Sun")
	s.Intensity = S.SunInt
	s.Spread = S.SunSpread
end

local function applyBlur()
	kill("Blur")
	if not (S.Master and S.Blur) then return end
	local b = make("BlurEffect","Blur")
	b.Size = S.BlurSize
end

local function applyAtmo()
	kill("Atmo")
	if not (S.Master and S.Atmo) then return end
	local a = make("Atmosphere","Atmo")
	a.Density = S.AtmoDen
	a.Offset = S.AtmoOff
	a.Color = S.AtmoCol
	a.Decay = S.AtmoDec
	a.Glare = S.AtmoGlare
	a.Haze = S.AtmoHaze
end

local function applySky()
	kill("Sky")
	if not (S.Master and S.SkyBox) then return end
	local conf = SKY_SETS[S.SkyId] or SKY_SETS[1]
	local sky = make("Sky","Sky")
	pcall(function()
		sky.SkyboxBk = conf.bk
		sky.SkyboxDn = conf.dn
		sky.SkyboxFt = conf.ft
		sky.SkyboxLf = conf.lf
		sky.SkyboxRt = conf.rt
		sky.SkyboxUp = conf.up
		sky.SunAngularSize = conf.sun
		sky.MoonAngularSize = conf.moon
		sky.StarCount = conf.star * 3000
	end)
end

local function applyGrade(id)
	local g = GRADE_MATRICES[id]
	if not g then return end
	S.CC = true
	S.CCBright = g.bright
	S.CCContrast = g.cont
	S.CCSat = g.sat
	S.CCTint = g.tint
	applyCC()
end

local function applyLightingCore()
	if not S.Master then
		for k,v in pairs(Orig) do
			if k ~= "Sky" then pcall(function() Lighting[k]=v end) end
		end
		return
	end
	if S.FullBright then
		Lighting.Brightness = 5
		Lighting.Ambient = Color3.new(1,1,1)
		Lighting.OutdoorAmbient = Color3.new(1,1,1)
		Lighting.FogEnd = 1e6
		Lighting.GlobalShadows = false
	else
		Lighting.Brightness = S.Bright
		Lighting.ExposureCompensation = S.Exposure
		Lighting.FogEnd = S.FogEnd
		Lighting.FogStart = S.FogStart
		Lighting.FogColor = S.FogCol
		Lighting.GlobalShadows = S.Shadows
		Lighting.ShadowSoftness = S.Softness
	end
	if S.TimeCtrl then Lighting.ClockTime = S.Clock end
	if S.TechFuture then pcall(function() Lighting.Technology = Enum.Technology.Future end) end
end

local function getParentGui()
	local ok,g = pcall(function() if typeof(gethui)=="function" then return gethui() end end)
	if ok and g then return g end
	local ok2,c = pcall(function() return game:GetService("CoreGui") end)
	if ok2 and c then return c end
	return LP:WaitForChild("PlayerGui")
end

local function applyVignette()
	kill("VigGui")
	if not (S.Master and S.Vignette) then return end
	local gui = Instance.new("ScreenGui")
	gui.Name = "OSH_VigGui"
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 99950
	gui.Parent = getParentGui()
	FX.VigGui = gui
	local f = Instance.new("Frame")
	f.Size = UDim2.fromScale(1,1)
	f.BackgroundColor3 = Color3.new(0,0,0)
	f.BackgroundTransparency = 1
	f.BorderSizePixel = 0
	f.Parent = gui
	local grad = Instance.new("UIGradient")
	grad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1-S.VigStr),
		NumberSequenceKeypoint.new(0.35, 1),
		NumberSequenceKeypoint.new(0.65, 1),
		NumberSequenceKeypoint.new(1, 1-S.VigStr),
	})
	grad.Parent = f
	-- dual axis approx via second frame
	local f2 = f:Clone()
	f2.Parent = gui
	local g2 = f2:FindFirstChildOfClass("UIGradient")
	if g2 then g2.Rotation = 90 end
end

local function applyCA()
	-- chromatic aberration approximation via dual CC not possible; use slight blur + tint pulse
	if not (S.Master and S.CA) then return end
	if S.CC then
		-- intensify existing
	end
end

local function applyUnderwater()
	if not (S.Master and S.Underwater) then
		return
	end
	S.CC = true
	S.CCTint = Color3.fromRGB(60, 120, 180)
	S.CCSat = -0.1
	S.CCBright = -0.05
	S.Blur = true
	S.BlurSize = 4
	S.Atmo = true
	S.AtmoDen = 0.55
	S.AtmoCol = Color3.fromRGB(40, 90, 140)
	S.FogEnd = 120
	applyCC()
	applyBlur()
	applyAtmo()
	applyLightingCore()
end

local function spawnWeather()
	clearWeather()
	if not (S.Master and S.Weather) then return end
	local cfg = WEATHER_CFG[S.WeatherType] or WEATHER_CFG.Rain
	local att = Instance.new("Part")
	att.Anchored = true
	att.CanCollide = false
	att.Transparency = 1
	att.Size = Vector3.new(1,1,1)
	att.Parent = workspace
	WeatherParts[#WeatherParts+1] = att
	local emitter = Instance.new("ParticleEmitter")
	emitter.Texture = cfg.tex
	emitter.Rate = S.WeatherRate
	emitter.Speed = NumberRange.new(cfg.speed*0.8, cfg.speed*1.2)
	emitter.Lifetime = NumberRange.new(cfg.life*0.7, cfg.life*1.3)
	emitter.Size = NumberSequence.new(cfg.size0, cfg.size1)
	emitter.Color = ColorSequence.new(cfg.color)
	emitter.LightEmission = cfg.light
	emitter.Drag = cfg.drag
	emitter.Acceleration = Vector3.new(0, cfg.accelY, 0)
	emitter.SpreadAngle = Vector2.new(cfg.spread, cfg.spread)
	emitter.Parent = att
	WeatherParts[#WeatherParts+1] = emitter
	weatherConn = RunService.RenderStepped:Connect(function()
		local cam = workspace.CurrentCamera
		if cam then
			att.CFrame = cam.CFrame * CFrame.new(0, 30, -20)
		end
	end)
end

local function applyAll()
	applyLightingCore()
	applyBloom()
	applyCC()
	applyDoF()
	applySun()
	applyBlur()
	applyAtmo()
	applySky()
	applyVignette()
	if S.Underwater then applyUnderwater() end
	if S.Weather then spawnWeather() else clearWeather() end
end

local function restoreAll()
	S.Master = false
	S.FullBright = false
	S.AutoCycle = false
	S.Weather = false
	S.Vignette = false
	S.Underwater = false
	if cycleConn then cycleConn:Disconnect() cycleConn=nil end
	clearWeather()
	for k in pairs(FX) do kill(k) end
	for k,v in pairs(Orig) do
		if k ~= "Sky" then pcall(function() Lighting[k]=v end) end
	end
end

local function setCycle(on)
	if cycleConn then cycleConn:Disconnect() cycleConn=nil end
	S.AutoCycle = on
	if not on then return end
	S.TimeCtrl = true
	cycleConn = RunService.RenderStepped:Connect(function(dt)
		if not (S.Master and S.AutoCycle) then return end
		S.Clock = (S.Clock + dt * S.CycleSpeed * 60) % 24
		Lighting.ClockTime = S.Clock
	end)
end

local function applyPreset(name)
	local p = PRESETS[name]
	if not p then return end
	S.Master = true
	for k,v in pairs(p) do
		if S[k] ~= nil or k == "SkyId" or k == "GradeId" then
			S[k] = v
		end
	end
	if p.GradeId then applyGrade(p.GradeId) end
	if p.SkyId then S.SkyBox = true S.SkyId = p.SkyId end
	applyAll()
end

